8	// The numbered steps DevDesk writes for the findings it builds itself
9	// (DEVDESK-752). Every function here is pure: the caller says what it ran and
10	// what the tool printed. A step is one imperative sentence in English US with
11	// one action; alternatives are separate steps. The Resolution of the same
12	// finding is untouched.
13	
14	// kustomizeMountStep is added for a kustomize image that could not find a path
15	// (see mountResolution): the container sees only what DevDesk mounts.
16	const kustomizeMountStep = "If this reference points outside the directory DevDesk mounts into the container, " +
17		"scan the enclosing directory or set scan.tools.kustomize.source: binary."
18	
19	// isLoadRestrictor reports whether kustomize refused a file outside the overlay
20	// directory.
21	func isLoadRestrictor(detail string) bool {
22		return strings.Contains(detail, "security; file") && strings.Contains(detail, "is not in or below")
23	}
