25	// renderSteps are the steps for a chart or an overlay that did not render.
26	// target is the overlay directory or the chart, relative to the scanned
27	// directory; detail is what the tool printed.
28	func renderSteps(source, target string, from ToolSource, detail string) []string {
29		if source != SourceKustomize {
30			return []string{
31				fmt.Sprintf("Run helm template %s and fix the first error it reports.", target),
32				fmt.Sprintf("If a dependency is missing, run helm dependency build %s.", target),
33			}
34		}
35		var steps []string
36		if isLoadRestrictor(detail) {
37			steps = []string{
38				"Reference a directory that has its own kustomization.yaml, or",
39				fmt.Sprintf("move the file below %s.", target),
40			}
41		} else {
42			steps = []string{fmt.Sprintf("Run kustomize build %s and fix the first error it reports.", target)}
43		}
44		if from == ToolSourceContainer &&
45			(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
46			steps = append(steps, kustomizeMountStep)
47		}
48		return steps
49	}
