51	// helmLintSteps are the steps for one message of helm lint: file is the finding's
52	// file and chart the chart directory.
53	func helmLintSteps(file, chart string) []string {
54		return []string{
55			fmt.Sprintf("Fix what helm lint reports in %s.", file),
56			fmt.Sprintf("Run helm lint %s again to confirm.", chart),
57		}
58	}
