66			field = strings.TrimSuffix(p.Path, "/") + "/" + m[1]
67		}
68		if field == "" {
69			field = "the resource"
70		}
71		release := "Kubernetes"
72		if version != "" {
73			release += " " + version
74		}
75		steps := []string{fmt.Sprintf("Correct %s so it matches the %s %s schema of %s.", field, r.Version, r.Kind, release)}
76		if rendered != "" {
77			steps = append(steps, fmt.Sprintf("Render it with %s and validate the output against %s.", rendered, release))
78		}
79		return steps
