func TestTheStepsGuardAcceptsWhatAStepsFunctionReturned(t *testing.T) {
	got, found := fieldViolations(parseGuardSources(t, map[string]string{"ok.go": stepsCleanSource}), stepsRule)
	if len(got) > 0 {
